import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import InputField from '../../../components/ui/InputField/InputField';
import Button from '../../../components/ui/Button/Button';

const CreatePrizePage = () => {
  return (
    <ContentWrapper title="Cadastrar Prêmio">
      <form>
        <InputField label="Nome do Prêmio" name="prize_name" placeholder="Ex: Ingresso de Cinema" />
        <InputField label="Custo em Selos" type="number" name="prize_cost" placeholder="Ex: 50" />
        <Button type="submit">Cadastrar Prêmio</Button>
      </form>
    </ContentWrapper>
  );
};

export default CreatePrizePage;
